async function freePort() { const s=net.createServer(); await new Promise((resolve,reject)=>{s.once('error',reject);s.listen(0,'127.0.0.1',resolve);}); const port=s.address().port; await new Promise(resolve=>s.close(resolve)); return port; }
let server;
async function stopServer() {
  if(!server)return;
  const p=server;
  if(!Number.isSafeInteger(p.pid)||p.pid<=0){server=null;return;}
  const sleep=ms=>new Promise(r=>setTimeout(r,ms));
  if(process.platform==='win32') {
    if(p.exitCode===null&&p.signalCode===null) {
      // Windows에서도 직접 생성한 PID의 하위 트리만 종료합니다. 이름별 전체 종료는 하지 않습니다.
      const killer=spawn('taskkill',['/PID',String(p.pid),'/T','/F'],{stdio:'ignore',windowsHide:true});
      const code=await new Promise((resolve,reject)=>{killer.once('error',reject);killer.once('exit',resolve);});
      must(code===0||p.exitCode!==null||p.signalCode!==null,'OWNED_SERVER_CLEANUP_FAILED');
    }
    for(let i=0;i<30&&p.exitCode===null&&p.signalCode===null;i++)await sleep(100);
    must(p.exitCode!==null||p.signalCode!==null,'OWNED_SERVER_STILL_RUNNING');
  } else {
    const alive=()=>{try{process.kill(-p.pid,0);return true;}catch(e){if(e.code==='ESRCH')return false;throw e;}};
    const signal=sig=>{try{process.kill(-p.pid,sig);}catch(e){if(e.code!=='ESRCH')throw e;}};
    // 직접 만든 전용 프로세스 그룹만 종료하고, 남은 프로세스도 재확인합니다.
    signal('SIGTERM');for(let i=0;i<40&&alive();i++)await sleep(100);
    if(alive()){signal('SIGKILL');for(let i=0;i<30&&alive();i++)await sleep(100);}
    must(!alive(),'OWNED_SERVER_GROUP_STILL_RUNNING');
  }
  server=null;
}
